div.script:
(function () {
    var el = document.getElementById('aeropay_poll');
    function poll() {
        fetch(el.dataset.statusUrl, {
            method: 'POST',
            headers: {'Content-Type': 'application/json'},
            body: JSON.stringify({jsonrpc: '2.0', method: 'call', params: {
                reference: el.dataset.reference, access_token: el.dataset.accessToken}}),
        }).then(function (r) { return r.json(); }).then(function (res) {
            var state = res.result && res.result.state;
            if (state && state !== 'draft' && state !== 'pending') {
                window.location = el.dataset.doneUrl;
            } else { setTimeout(poll, 4000); }
        }).catch(function () { setTimeout(poll, 8000); });
    }
    setTimeout(poll, 3000);
})();
